window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-55e7802c3cda3ac4"]={"versions": [{"id": "FIG-55e7802c3cda3ac4", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Platform Health Management (PHM) im AUTOSAR Adaptive Manifest. Dargestellt ist die Spezialisierungshierarchie und Kompositionsstruktur für Health Channels als Port-Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Abstrakte Basisklasse, stereotypisiert als <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><code>PlatformHealthManagementInterface</code>: Abstrakte Spezialisierung von <code>PortInterface</code>.\n</li><li><code>PhmHealthChannelInterface</code>: Konkrete Spezialisierung von <code>PlatformHealthManagementInterface</code>. Besitzt das Attribut <code>+ healthChannelId :PositiveInteger</code>.\n</li><li><code>PhmHealthChannelStatus</code>: Stereotypisiert als <code>«AtpFeature»</code>. Besitzt das Attribut <code>+ statusId :PositiveInteger</code>.\n</li><li>Beziehung: <code>PhmHealthChannelInterface</code> aggregiert per Komposition (<code>+status</code>) <code>0..*</code> Instanzen von <code>PhmHealthChannelStatus</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell ohne Verhaltens- oder Sequenzpfade. Beschreibt die Konfigurationsstruktur, über welche ein Health Channel mit einer Kennung (<code>healthChannelId</code>) und einer Menge möglicher Statuswerte (<code>statusId</code>) im Manifest deklariert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevanter Bestandteil für die Modellierung und Validierung von Überwachungskanälen im AUTOSAR Adaptive Platform Health Management. <code>healthChannelId</code> und <code>statusId</code> müssen als positive Ganzzahlen modelliert sein. Jedem Statuswert eines Health Channels ist genau ein <code>PhmHealthChannelStatus</code>-Element zugeordnet.</p>"}, {"id": "FIG-27f06087474c5e7b", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Platform Health Management (PHM) im AUTOSAR Adaptive Manifest. Dargestellt ist die Spezialisierungshierarchie und Kompositionsstruktur für Health Channels als Port-Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Abstrakte Basisklasse, stereotypisiert als <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><code>PlatformHealthManagementInterface</code>: Abstrakte Spezialisierung von <code>PortInterface</code>.\n</li><li><code>PhmHealthChannelInterface</code>: Konkrete Spezialisierung von <code>PlatformHealthManagementInterface</code>. Besitzt das Attribut <code>+ healthChannelId: PositiveInteger</code>.\n</li><li><code>PhmHealthChannelStatus</code>: Stereotypisiert als <code>«AtpFeature»</code>. Besitzt das Attribut <code>+ statusId: PositiveInteger</code>.\n</li><li>Beziehung: <code>PhmHealthChannelInterface</code> aggregiert per Komposition (<code>+status</code>) <code>0..*</code> Instanzen von <code>PhmHealthChannelStatus</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell ohne Verhaltens- oder Sequenzpfade. Beschreibt die Konfigurationsstruktur, über welche ein Health Channel mit einer Kennung (<code>healthChannelId</code>) und einer Menge möglicher Statuswerte (<code>statusId</code>) im Manifest deklariert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevanter Bestandteil für die Modellierung und Validierung von Überwachungskanälen im AUTOSAR Adaptive Platform Health Management. <code>healthChannelId</code> und <code>statusId</code> müssen als positive Ganzzahlen modelliert sein. Jedem Statuswert eines Health Channels ist genau ein <code>PhmHealthChannelStatus</code>-Element zugeordnet.</p>"}, {"id": "FIG-57b1a79465b9f67a", "releases": ["R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Platform Health Management (PHM) im AUTOSAR Adaptive Manifest. Dargestellt ist die Spezialisierungshierarchie und Kompositionsstruktur für Health Channels als Port-Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Abstrakte Basisklasse, stereotypisiert als <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><code>PlatformHealthManagementInterface</code>: Abstrakte Spezialisierung von <code>PortInterface</code>.\n</li><li><code>PhmHealthChannelInterface</code>: Konkrete Spezialisierung von <code>PlatformHealthManagementInterface</code> ohne eigene Attribute.\n</li><li><code>PhmHealthChannelStatus</code>: Stereotypisiert als <code>«AtpFeature»</code>. Besitzt das Attribut <code>+ statusId: PositiveInteger</code>.\n</li><li>Beziehung: <code>PhmHealthChannelInterface</code> aggregiert per Komposition (<code>+status</code>) <code>0..*</code> Instanzen von <code>PhmHealthChannelStatus</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell ohne Verhaltens- oder Sequenzpfade. Beschreibt die Konfigurationsstruktur, über welche ein Health Channel ohne explizites Kanal-ID-Attribut mit einer Menge möglicher Statuswerte (<code>statusId</code>) im Manifest deklariert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevanter Bestandteil für die Modellierung und Validierung von Überwachungskanälen im AUTOSAR Adaptive Platform Health Management. <code>PhmHealthChannelInterface</code> besitzt keine eigene Kennung auf Klassenebene. <code>statusId</code> muss als positive Ganzzahl modelliert sein. Jedem Statuswert eines Health Channels ist genau ein <code>PhmHealthChannelStatus</code>-Element zugeordnet.</p>"}, {"id": "FIG-d7415af05a928fa5", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Platform Health Management (PHM) im AUTOSAR Adaptive Manifest. Dargestellt ist die Spezialisierungshierarchie und Kompositionsstruktur für Health Channels als Port-Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Abstrakte Basisklasse, stereotypisiert als <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><code>PlatformHealthManagementInterface</code>: Abstrakte Spezialisierung von <code>PortInterface</code>.\n</li><li><code>PhmHealthChannelInterface</code>: Konkrete Spezialisierung von <code>PlatformHealthManagementInterface</code> ohne eigene Attribute.\n</li><li><code>PhmHealthChannelStatus</code>: Stereotypisiert als <code>«AtpFeature»</code>. Besitzt die Attribute <code>+ statusId: PositiveInteger [0..1]</code> und <code>+ triggersRecoveryNotification: Boolean [0..1]</code>.\n</li><li>Beziehung: <code>PhmHealthChannelInterface</code> aggregiert per Komposition (<code>+status</code>) <code>0..*</code> Instanzen von <code>PhmHealthChannelStatus</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell ohne Verhaltens- oder Sequenzpfade. Beschreibt die Konfigurationsstruktur, über welche ein Health Channel mit einer Menge möglicher Statuswerte deklariert wird; einzelne Statuswerte können optional eine Kennung (<code>statusId</code>) besitzen und festlegen, ob sie eine Benachrichtigung zur Fehlerbehebung (<code>triggersRecoveryNotification</code>) auslösen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevanter Bestandteil für die Modellierung und Validierung von Überwachungskanälen im AUTOSAR Adaptive Platform Health Management. Beide Attribute von <code>PhmHealthChannelStatus</code> (<code>statusId</code> und <code>triggersRecoveryNotification</code>) sind optional (Multiplizität <code>[0..1]</code>). <code>triggersRecoveryNotification</code> steuert auf Modellebene, ob bei Eintritt des jeweiligen Status eine Recovery-Benachrichtigung ausgelöst werden soll.</p>"}, {"id": "FIG-ee4e4692bb5296c3", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Platform Health Management (PHM) im AUTOSAR Adaptive Manifest. Dargestellt ist die Spezialisierungshierarchie und Kompositionsstruktur für Health Channels als Port-Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Abstrakte Basisklasse, stereotypisiert als <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><code>PlatformHealthManagementInterface</code>: Abstrakte Spezialisierung von <code>PortInterface</code>.\n</li><li><code>PhmHealthChannelInterface</code>: Konkrete Spezialisierung von <code>PlatformHealthManagementInterface</code> ohne eigene Attribute.\n</li><li><code>PhmHealthChannelStatus</code>: Stereotypisiert als <code>«AtpFeature»</code>. Besitzt die Attribute <code>+ statusId: PositiveInteger [0..1]</code> und <code>+ triggersRecoveryNotification: Boolean [0..1]</code>.\n</li><li>Beziehung: <code>PhmHealthChannelInterface</code> aggregiert per Komposition (<code>+status</code>) <code>0..*</code> Instanzen von <code>PhmHealthChannelStatus</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell ohne Verhaltens- oder Sequenzpfade. Beschreibt die Konfigurationsstruktur, über welche ein Health Channel mit einer Menge möglicher Statuswerte deklariert wird; einzelne Statuswerte können optional eine Kennung (<code>statusId</code>) besitzen und festlegen, ob sie eine Benachrichtigung zur Fehlerbehebung (<code>triggersRecoveryNotification</code>) auslösen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevanter Bestandteil für die Modellierung und Validierung von Überwachungskanälen im AUTOSAR Adaptive Platform Health Management. Beide Attribute von <code>PhmHealthChannelStatus</code> (<code>statusId</code> und <code>triggersRecoveryNotification</code>) sind optional (Multiplizität <code>[0..1]</code>). <code>triggersRecoveryNotification</code> steuert auf Modellebene, ob bei Eintritt des jeweiligen Status eine Recovery-Benachrichtigung ausgelöst werden soll.</p>"}, {"id": "FIG-7fc55b69f0da8ae8", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Platform Health Management (PHM) im AUTOSAR Adaptive Manifest. Dargestellt ist die Spezialisierungshierarchie und Kompositionsstruktur für Health Channels als Port-Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Abstrakte Basisklasse, stereotypisiert als <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><code>PlatformHealthManagementInterface</code>: Abstrakte Spezialisierung von <code>PortInterface</code>.\n</li><li><code>PhmHealthChannelInterface</code>: Konkrete Spezialisierung von <code>PlatformHealthManagementInterface</code> ohne eigene Attribute.\n</li><li><code>PhmHealthChannelStatus</code>: Stereotypisiert als <code>«AtpFeature»</code>. Besitzt die Attribute <code>+ statusId: PositiveInteger [0..1]</code> und <code>+ triggersRecoveryNotification: Boolean [0..1]</code>.\n</li><li>Beziehung: <code>PhmHealthChannelInterface</code> aggregiert per Komposition (<code>+status</code>) <code>0..*</code> Instanzen von <code>PhmHealthChannelStatus</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell ohne Verhaltens- oder Sequenzpfade. Beschreibt die Konfigurationsstruktur, über welche ein Health Channel mit einer Menge möglicher Statuswerte deklariert wird; einzelne Statuswerte können optional eine Kennung (<code>statusId</code>) besitzen und festlegen, ob sie eine Benachrichtigung zur Fehlerbehebung (<code>triggersRecoveryNotification</code>) auslösen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevanter Bestandteil für die Modellierung und Validierung von Überwachungskanälen im AUTOSAR Adaptive Platform Health Management. Beide Attribute von <code>PhmHealthChannelStatus</code> (<code>statusId</code> und <code>triggersRecoveryNotification</code>) sind optional (Multiplizität <code>[0..1]</code>). <code>triggersRecoveryNotification</code> steuert auf Modellebene, ob bei Eintritt des jeweiligen Status eine Recovery-Benachrichtigung ausgelöst werden soll.</p>"}, {"id": "FIG-8bdf546628244866", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Platform Health Management (PHM) im AUTOSAR Adaptive Manifest. Dargestellt ist die Spezialisierungshierarchie und Kompositionsstruktur für Health Channels als Port-Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Abstrakte Basisklasse, stereotypisiert als <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code>.\n</li><li><code>PlatformHealthManagementInterface</code>: Abstrakte Spezialisierung von <code>PortInterface</code>.\n</li><li><code>PhmHealthChannelInterface</code>: Konkrete Spezialisierung von <code>PlatformHealthManagementInterface</code> ohne eigene Attribute.\n</li><li><code>PhmHealthChannelStatus</code>: Stereotypisiert als <code>«AtpFeature»</code>. Besitzt die Attribute <code>+ statusId: PositiveInteger [0..1]</code> und <code>+ triggersRecoveryNotification: Boolean [0..1]</code>.\n</li><li>Beziehung: <code>PhmHealthChannelInterface</code> aggregiert per Komposition (<code>+status</code>) <code>0..*</code> Instanzen von <code>PhmHealthChannelStatus</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell ohne Verhaltens- oder Sequenzpfade. Beschreibt die Konfigurationsstruktur, über welche ein Health Channel mit einer Menge möglicher Statuswerte deklariert wird; einzelne Statuswerte können optional eine Kennung (<code>statusId</code>) besitzen und festlegen, ob sie eine Benachrichtigung zur Fehlerbehebung (<code>triggersRecoveryNotification</code>) auslösen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevanter Bestandteil für die Modellierung und Validierung von Überwachungskanälen im AUTOSAR Adaptive Platform Health Management. Beide Attribute von <code>PhmHealthChannelStatus</code> (<code>statusId</code> und <code>triggersRecoveryNotification</code>) sind optional (Multiplizität <code>[0..1]</code>). <code>triggersRecoveryNotification</code> steuert auf Modellebene, ob bei Eintritt des jeweiligen Status eine Recovery-Benachrichtigung ausgelöst werden soll.</p>"}], "trans": [{"from": "FIG-55e7802c3cda3ac4", "to": "FIG-27f06087474c5e7b", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>PhmHealthChannelInterface: Leerzeichen vor dem Doppelpunkt beim Attribut <code>+ healthChannelId :PositiveInteger</code> entfernt (<code>+ healthChannelId: PositiveInteger</code>).\n</li><li>PhmHealthChannelStatus: Leerzeichen vor dem Doppelpunkt beim Attribut <code>+ statusId :PositiveInteger</code> entfernt (<code>+ statusId: PositiveInteger</code>).\n</li></ul>"}, {"from": "FIG-27f06087474c5e7b", "to": "FIG-57b1a79465b9f67a", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>PhmHealthChannelInterface: Das Attribut <code>+ healthChannelId: PositiveInteger</code> sowie das untere Attributfach entfallen vollständig.\n</li></ul>"}, {"from": "FIG-57b1a79465b9f67a", "to": "FIG-d7415af05a928fa5", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>PhmHealthChannelStatus: Kardinalität des Attributs <code>statusId</code> von obligatorisch (implizit 1) auf optional geändert (<code>+ statusId: PositiveInteger [0..1]</code>).\n</li><li>PhmHealthChannelStatus: Attribut <code>+ triggersRecoveryNotification: Boolean [0..1]</code> neu hinzugefügt.\n</li></ul>"}, {"from": "FIG-d7415af05a928fa5", "to": "FIG-ee4e4692bb5296c3", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ee4e4692bb5296c3", "to": "FIG-7fc55b69f0da8ae8", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7fc55b69f0da8ae8", "to": "FIG-8bdf546628244866", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
